def find_permutation(n, k):
    permutation = list(range(1, n + 1))
    distinct_differences = set()

    for i in range(n - 1):
        distinct_differences.add(abs(permutation[i] - permutation[i + 1]))

    while len(distinct_differences) < k:
        for i in range(n - 1):
            new_difference = abs(permutation[i] - permutation[i + 1])
            if new_difference not in distinct_differences:
                distinct_differences.add(new_difference)
                break
        else:
            # If we have checked all possible pairs and still need more distinct differences,
            # we need to swap elements to create new differences.
            for i in range(n - 1):
                for j in range(i + 1, n):
                    if abs(permutation[i] - permutation[j]) not in distinct_differences:
                        permutation[i], permutation[j] = permutation[j], permutation[i]
                        distinct_differences.add(abs(permutation[i] - permutation[j]))
                        break
                if len(distinct_differences) >= k:
                    break
            break

    return permutation

